/// Daily consumption over the window the ledger keeps.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UsageHistory {
    /// First day covered.
    pub start_date: String,
    /// Last day covered.
    pub end_date: String,
    /// One entry per day and source that saw usage, oldest first.
    #[serde(default)]
    pub days: Vec<UsageDay>,
}

/// One metered group, with every window that has a limit.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UsageScope {
    /// Identifier of the metered group.
    pub scope: String,
    /// Name of the group, as an admin sees it.
    pub human_name: String,
    /// ``request`` counts calls; ``item`` counts rows returned.
    pub kind: String,
    /// Which product the group meters: ``api`` for direct requests, ``mcp`` for AI clients. The
    /// two never share a counter.
    pub section: String,
    /// Every window that has a limit configured.
    #[serde(default)]
    pub windows: Vec<UsageWindow>,
}

/// Consumption of one window, e.g. requests in the current hour.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UsageWindow {
    /// Which window this is: rps, rpm, rph, rpd, rpmonth, or an item window.
    pub window: String,
    /// Most that may be spent in this window.
    pub limit: i64,
    /// Spent so far in this window.
    pub used: i64,
    /// Still available in this window.
    pub remaining: i64,
    /// Seconds until the window resets. The window starts on its first request rather than on
    /// the clock, so this is what is left of it.
    pub reset_in: i64,
}

/// A paid-partnership signal found in one piece of content.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VettingDisclosure {
    /// The content the signal is in.
    pub content_id: String,
    /// Link to that content, blank when unknown.
    pub content_url: String,
    /// Where it was found: `frame`, `title`, `caption` or `audio`.
    pub source: String,
    /// What kind of signal it is, for example `sponsorship`.
    pub kind: String,
    /// The disclosure wording itself.
    pub text: String,
    /// Seconds into the video, or `null` when it is not timed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub time_seconds: Option<i64>,
}

/// How much of the creator's catalogue raised a flag.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VettingSummary {
    /// Flags raised across every criterion.
    pub total_violations: i64,
    /// Distinct content items carrying at least one flag.
    pub affected_contents: i64,
}

/// The creator's recurring subjects, with what each is based on.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VettingTopThemes {
    /// The themes, strongest first.
    #[serde(default)]
    pub top_themes: Vec<String>,
    /// `top_themes`: one grounded entry per theme.
    pub grounding: serde_json::Value,
}

/// One criterion raised against one piece of the creator's content.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VettingViolation {
    /// Stable id for this flag, as `{content_id}_{type}`.
    pub violation_id: String,
    /// The criterion. One of `ILLEGAL_ACTS`, `HATE_SPEECH`, `MINOR_SAFETY`, `TERRORISM`,
    /// `GRAPHIC_VIOLENCE`, `ADULT_CONTENT`, `ARMS_AND_AMMUNITION`, `SENSITIVE_NEWS_TRAGEDY`,
    /// `MISINFORMATION`, `PROFANITY`, `ALCOHOL_AND_TOBACCO`, `POLITICS`, or `USER_DEFINED` for
    /// a criterion you supplied.
    #[serde(rename = "type")]
    pub r#type: String,
    /// The criterion's display name.
    pub value: String,
    /// What the criterion covers.
    pub description: String,
    /// Why this content was judged to breach the criterion.
    pub reason: String,
    /// The passage the judgement rests on, verbatim.
    pub evidence_quote: String,
    /// Where the quote came from: `title`, `ai_summary`, `transcription`, `text_overlay`,
    /// `vetting_observations` or `none`. New values can be added, so treat an unknown one as
    /// `none` rather than failing.
    pub evidence_field: String,
    /// The content the flag is against.
    pub content_id: String,
    /// Always `yes`. Content that passed is not listed.
    pub violation: String,
    /// How serious the flag is: `high`, `medium`, `low` or `N/A`.
    pub severity: String,
}

/// An event type a subscription may ask for.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookAvailableEvent {
    /// Event type identifier, e.g. creator_vetting.completed.
    pub event: String,
    /// Human-readable grouping label.
    pub group: String,
    /// What triggers the event and what the payload holds.
    pub description: String,
}

/// The carried content of a push. The populated key depends on `delivery_mode`. `manifest`
/// deliveries populate `files` (downloadable snapshot files) and, for the content resource,
/// `statistics`. `inline` deliveries populate `items` (the rows directly). The unused key
/// is omitted.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookData {
    /// Total number of rows in this delivery, summed across `files` or equal to the length of
    /// `items`.
    pub item_count: i64,
    /// Aggregate totals over the snapshot, including post count, views, engagement, earned
    /// media value, and unique creators. Present only on `content.snapshot`; absent for creator
    /// and event pushes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub statistics: Option<serde_json::Value>,
    /// Manifest mode only. The downloadable snapshot files; retrieve each `download_url` and
    /// stream the NDJSON rows. Absent in `inline` mode.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub files: Option<Vec<WebhookFile>>,
    /// Inline mode only. The delivered rows themselves, in the same shape returned by the
    /// matching REST endpoint. Absent in `manifest` mode.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub items: Option<Vec<serde_json::Value>>,
}

/// Confirmation that a webhook resource was deleted.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookDeleteAcknowledgement {
    /// Always true; confirms the webhook resource delete was acknowledged.
    pub acknowledged: bool,
    /// Action that was performed. Always 'delete'.
    pub action: String,
    /// Completion status of the action. Always 'complete'.
    pub status: String,
}

/// One attempt to deliver one push, with its outcome.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookDelivery {
    /// Encoded identifier of the webhook delivery.
    pub id: String,
    /// Encoded identifier of the parent subscription.
    pub subscription: String,
    /// When this delivery is scheduled to be sent.
    pub scheduled_at: String,
    /// Number of delivery attempts made so far.
    pub attempt_count: i64,
    /// Current state of the delivery.
    pub state: StateEnum,
    /// HTTP status code returned by the most recent attempt.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_status_code: Option<i64>,
    /// Error message from the most recent failed attempt.
    pub last_error: String,
    /// Excerpt of the response body returned by the endpoint.
    pub response_excerpt: String,
    /// When the delivery finished (succeeded or exhausted).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub finished_at: Option<String>,
    /// Number of items included in the delivered payload.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub item_count: Option<i64>,
    /// SHA-256 checksum of the delivered payload.
    pub sha256: String,
    /// Size of the delivered payload in bytes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub size_bytes: Option<i64>,
    /// Timestamp set once when the row is first created.
    pub created: String,
    /// Timestamp updated automatically on every save.
    pub modified: String,
}

/// One downloadable snapshot file in a manifest push. `files` is an array, so read every
/// entry rather than assuming one.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookFile {
    /// File encoding. Always `ndjson` (newline-delimited JSON, with one row per line).
    pub format: String,
    /// Unix epoch seconds after which `download_url` stops working. Fetch the file before this
    /// time.
    pub expires_at: i64,
    /// Hex SHA-256 of the file body. Use it to verify the download.
    pub sha256: String,
    /// Size of the file in bytes.
    pub size_bytes: i64,
    /// Number of rows in this file.
    pub item_count: i64,
    /// Signed, time-limited URL from which to retrieve the file. Expires at `expires_at`.
    pub download_url: String,
}

/// The outer payload Zelf POSTs to receivers, uniform across all pushes. Top-level fields
/// are delivery metadata and remain identical across modes. `data` carries the content;
/// which key inside it is populated (`files` or `items`) is determined by `delivery_mode`.
/// `manifest` deliveries use `data.files`, while `inline` event pushes use `data.items`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookPush {
    /// Unique id of this delivery attempt, stable across retries of the same push.
    pub id: String,
    /// Event type. `<resource>.snapshot` for scheduled snapshots (`content.snapshot`,
    /// `creator.snapshot`), or the event name for event pushes (`creator_vetting.completed`).
    #[serde(rename = "type")]
    pub r#type: String,
    /// Id of the subscription that produced this push.
    pub subscription_id: String,
    /// Unix epoch seconds at which Zelf sent this push.
    pub delivered_at: i64,
    /// `true` for production data; `false` for test deliveries.
    pub livemode: bool,
    /// Resource the push covers (`content` or `creator`) for snapshots; `null` for event
    /// pushes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource: Option<String>,
    /// The subscription's stored filters that scoped this snapshot, using the same query params
    /// as the matching list operation (`content.list` or `creators.list`). Empty for event
    /// pushes.
    pub resource_filters: serde_json::Value,
    /// `manifest`: `data.files` holds downloadable snapshot files. `inline`: `data.items` holds
    /// the rows directly.
    pub delivery_mode: WebhookPushDeliveryMode,
    /// The push payload. See `delivery_mode` for which key inside is populated.
    pub data: WebhookData,
}

/// A signing secret, identified by its prefix rather than its value.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSecret {
    /// Encoded identifier of the webhook secret.
    pub id: String,
    /// Type of webhook this secret applies to.
    pub kind: KindEnum,
    /// Non-sensitive prefix of the secret, shown for identification.
    pub secret_prefix: String,
    /// Whether this secret is currently active.
    pub is_active: bool,
    /// Whether this is the default secret for the brand and kind.
    pub is_default: bool,
    /// Timestamp set once when the row is first created.
    pub created: String,
    /// Timestamp updated automatically on every save.
    pub modified: String,
}

/// The WebhookSecretCreateRequest object.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSecretCreateRequest {
    /// Whether the secret is for snapshot or event webhooks.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kind: Option<KindEnum>,
    /// Set this secret as the default for its kind.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub make_default: Option<bool>,
}

/// A secret just created or rotated, carrying the value once. Store it now: later reads
/// return the prefix alone.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSecretCreated {
    /// Encoded identifier of the webhook secret.
    pub id: String,
    /// Type of webhook this secret applies to.
    pub kind: KindEnum,
    /// Non-sensitive prefix of the secret, shown for identification.
    pub secret_prefix: String,
    /// Whether this secret is currently active.
    pub is_active: bool,
    /// Whether this is the default secret for the brand and kind.
    pub is_default: bool,
    /// Timestamp set once when the row is first created.
    pub created: String,
    /// Timestamp updated automatically on every save.
    pub modified: String,
    /// Full signing secret, returned only once on creation.
    pub secret: String,
}

/// A registered endpoint and the events it receives.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSubscription {
    /// Encoded identifier of the webhook subscription.
    pub id: String,
    /// Type of webhook this subscription delivers.
    pub kind: KindEnum,
    /// Resource type the subscription is for (content or creator).
    pub resource: ResourceEnum,
    /// Event types the subscription listens for.
    #[serde(default)]
    pub event_types: Vec<String>,
    /// Filters applied to select which resources are delivered.
    pub resource_filters: serde_json::Value,
    /// Destination URL where webhook payloads are sent.
    pub url: String,
    /// Custom HTTP headers to include with each delivery.
    pub custom_headers: serde_json::Value,
    /// Hours between snapshot deliveries.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interval_hours: Option<i64>,
    /// Max rows a real snapshot delivers. Null or 0 falls back to the default item limit.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_items: Option<i64>,
    /// Public prefix of the subscription signing secret.
    pub secret_prefix: String,
    /// Whether this subscription is active and will be dispatched.
    pub enabled: bool,
    /// When this subscription last dispatched a delivery.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_run_at: Option<String>,
    /// Outcome status of the most recent delivery. Empty until the subscription has dispatched
    /// for the first time.
    pub last_status: LastStatusEnum,
    /// Timestamp set once when the row is first created.
    pub created: String,
    /// Timestamp updated automatically on every save.
    pub modified: String,
}

/// The WebhookSubscriptionCreateRequest object.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSubscriptionCreateRequest {
    /// Whether the subscription is snapshot or event based.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub kind: Option<KindEnum>,
    /// Resource type for snapshot subscriptions.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource: Option<ResourceEnum>,
    /// Event names the subscription listens for.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub event_types: Option<Vec<String>>,
    /// Filters that scope which resources are delivered.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource_filters: Option<serde_json::Value>,
    /// Destination URL where webhook payloads are sent.
    pub url: String,
    /// Extra HTTP headers sent with each webhook request.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub custom_headers: Option<serde_json::Value>,
    /// Hours between snapshot deliveries. Allowed values: 4, 6, 12, 24, 168, 720. The first
    /// snapshot is sent within minutes of the subscription being saved, not after a full
    /// interval has passed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interval_hours: Option<i64>,
    /// Maximum number of items per delivery.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_items: Option<i64>,
    /// Type of signing secret to attach to the subscription.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub secret_type: Option<SecretTypeEnum>,
}

/// A subscription just created, with the signing secret attached. The secret is shown on
/// this response only and never again.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WebhookSubscriptionCreated {
    /// Encoded identifier of the webhook subscription.
    pub id: String,
    /// Type of webhook this subscription delivers.
    pub kind: KindEnum,
    /// Resource type the subscription is for (content or creator).
    pub resource: ResourceEnum,
    /// Event types the subscription listens for.
    #[serde(default)]
    pub event_types: Vec<String>,
    /// Filters applied to select which resources are delivered.
    pub resource_filters: serde_json::Value,
    /// Destination URL where webhook payloads are sent.
    pub url: String,
    /// Custom HTTP headers to include with each delivery.
    pub custom_headers: serde_json::Value,
    /// Hours between snapshot deliveries.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interval_hours: Option<i64>,
    /// Max rows a real snapshot delivers. Null or 0 falls back to the default item limit.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_items: Option<i64>,
    /// Public prefix of the subscription signing secret.
    pub secret_prefix: String,
    /// Full signing secret, returned only once, at the moment it is minted. Null when the
    /// subscription reuses the brand's existing default secret, since that value is never shown
    /// twice.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub secret: Option<String>,
    /// Whether this subscription is active and will be dispatched.
    pub enabled: bool,
    /// Timestamp set once when the row is first created.
    pub created: String,
}
